static BakeReport report(List<Tray> trays) {
    List<Cookie> cookies = trays.stream().flatMap(t -> t.cookies().stream()).toList();
    Map<String, Cookie> byId = cookies.stream()
            .collect(Collectors.toMap(Cookie::id, c -> c));               // throws on a repeated id

    List<Cookie> golden = cookies.stream().filter(c -> c.status() == GOLDEN).toList();
    return new BakeReport(
            cookies.size(),
            golden.stream().mapToInt(Cookie::grams).sum(),
            cookies.stream().map(Cookie::nibbledGrams).filter(Objects::nonNull)
                    .mapToInt(Integer::intValue).sum(),
            golden.stream().collect(Collectors.groupingBy(Cookie::flavor,
                    LinkedHashMap::new,                                     // or no order is promised
                    Collectors.summingInt(c -> c.grams() - biteOf(c)))),
            cookies.stream().filter(c -> c.status() == BURNT).map(Cookie::id).toList(),
            golden.stream().max(Comparator.comparingInt(Cookie::grams)));   // Optional<Cookie>
}

kotlin.src:
fun report(trays: List<Tray>): BakeReport {
    val cookies = trays.flatMap { it.cookies }
    val repeated = cookies.groupingBy { it.id }.eachCount().filterValues { it > 1 }.keys
    require(repeated.isEmpty()) { "duplicate cookie ids: ${repeated.joinToString()}" }   // associateBy would not

    val golden = cookies.filter { it.status == GOLDEN }
    return BakeReport(
        cookieCount = cookies.size,
        goldenGrams = golden.sumOf { it.grams },
        nibbledGrams = cookies.mapNotNull { it.nibbledGrams }.sum(),
        netByFlavor = golden.groupBy { it.flavor }                         // first-seen order
            .mapValues { (_, cs) -> cs.sumOf { it.grams - (it.nibbledGrams ?: 0) } },
        burntIds = cookies.filter { it.status == BURNT }.map { it.id },
        largestGolden = golden.maxByOrNull { it.grams },                   // Cookie?, null when none
    )
}

